INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-069', 'AUDT', 'P2', 'OPEN', NULL, 'scripts/audit/adversarial_pass_audit.py; scripts/audit/research_batch_dod.py', 'No gate scoped to a session examines a term-adjudication-only batch. adversarial_pass_audit.py (RC4) derives its subject tables from the 2026-08-19 RULE''s limb (a), which does not list term_adjudications, so for session_2026-10-30-d4-ramp-term-adjudication it prints EXAMINED: 0 and ''owes no pass''; research_batch_dod.py scopes R16, R16-adjudicate, R17, R12 and R13 to the batch''s admissions (this batch admits none), and fails R1, R9a and R9b as an untouched session because it logged no searches. A wrong term_id or a misquoted rationale in a term_adjudications row therefore ships with every session-scoped gate green or inapplicable. Found by the antagonist pass of that session (adversarial finding, severity HIGH). Not patched in the batch: tooling ships in its own PR (CLAUDE.md rule 10). Fix shape for that PR: derive RC4''s subject tables from the schema (or add term_adjudications to the limb, which the script''s docstring ties to OQ-8), and have the DoD treat an adjudication-only batch as in scope for R16-adjudicate and out of scope for R1, R9a and R9b.', '2026-10-30 21:07', 'session_2026-10-30-d4-ramp-term-adjudication', '2026-10-30 21:07', 'session_2026-10-30-d4-ramp-term-adjudication', NULL, NULL, NULL, NULL, NULL);
